definition.script:
pipeline {
    agent any

    stages {
        stage('1. GitHub 소스코드 가져오기') {
            steps {
                // 본인의 GitHub 저장소 주소로 변경하세요
                git branch: 'main', url: 'https://github.com/youbccc/work.git'
            }
        }

        stage('2. 기존 컨테이너 정리') {
            steps {
                // 이미 실행 중인 컨테이너가 있다면 중지 및 삭제 (오류 방지용 || true)
                sh 'docker stop kkk-work || true'
                sh 'docker rm kkk-work || true'
            }
        }

        stage('3. Dockerfile 기반 이미지 빌드') {
            steps {
                // Git에서 가져온 Dockerfile을 빌드
                sh 'docker build -t kkk-image:latest .'
            }
        }

        stage('4. 새 컨테이너 실행 (배포)') {
            steps {
                // 빌드된 이미지로 새 컨테이너 실행
                sh 'docker run -d --name kkk-work kkk-image:latest tail -f /dev/null'
            }
        }
    }
}
